declare const tools: { mcp__pixellab__edit_animation(args: {
  // The edit to make on every frame: 'add a red cape', 'make the sword glow blue', 'give him a helmet'. Poses and motion stay as they are.
  description: string;
  // The animation, in order. One entry for a whole animation: `character:<id>:<direction>:<animation>` or `object:<id>:<direction>:<animation>` (the [group: …] id or name get_character / get_object shows), `job:<id>` (an animate_image / edit_image result), a GIF URL, or a multi-frame pixelart_workbench result. Or one entry per frame: https/data URLs, `upload:<id>`, `job:<id>:<index>` or base64 PNGs. Every frame the same size, max 256x256.
